async function 加载实例(page = 1) {
      
    if (!开发者UID || !开发者密码) {
        alert('请先登录', false);
        return;
    }
    
    const 对接实例_加载动画 = document.getElementById('对接实例_加载动画');

    if (对接实例_加载动画) 对接实例_加载动画.style.display = 'flex';
    
  
        const params = {
            action:  'get_apps',
            password: 开发者安全密码,
            page: page,
            limit: 对接实例_每页数量
        };
                
        if (对接实例_当前搜索关键词 !== '') {
            params.search_name = 对接实例_当前搜索关键词;
        }

        const result = await POSTPHP(开发者UID, 开发者密码, 开发者Token, 获取API链接('app.php'), params);

        if (result.success) {
            
            const appsData = result.data.apps || [];//对接实例组
            const paginationData = result.data.pagination || { page: page, limit: 对接实例_每页数量, total: appsData.length, pages: 1 };//页码
            const statisticsData = result.data.statistics || { total_count: appsData.length, active_count: 0, inactive_count: appsData.length };//统计
            
            
            对接实例_当前页数量 = appsData.length;//获取


            
            
            对接实例_总页数 = paginationData.pages || 1;
            对接实例_当前页码 = page;
            
            
            
            
    对接实例_重置所有选中();
    
    
            对接实例_渲染表格(appsData);
            
            
            
            //更新标题和统计数据
            对接实例_更新统计显示数据(statisticsData);
            
            if (对接实例_加载动画) 对接实例_加载动画.style.display = 'none';
            刷新实例额度();
            
        } else {
            alert('加载应用失败: ' + result.message, false);
            if (对接实例_加载动画) 对接实例_加载动画.style.display = 'none';
        }
        
   
}



