async function 打开云控面板(appId, button) {
    if (button) button.disabled = true;
    try {
        const result = await POSTPHP(开发者UID, 开发者密码, 开发者Token, 获取API链接('app.php'), {
            action: 'open_cloud_control', app_id: appId, password: 开发者安全密码
        });
        if (!result.success || !result.data || !result.data.url) {
            const msg = (result && result.message) || '打开云控面板失败';
            if (msg.indexOf('会员') !== -1) {
                显示会员专享弹窗(msg);
                return;
            }
            alert(msg, false);
            return;
        }
        window.location.assign(result.data.url);
    } catch (error) {
        alert('打开云控面板失败，请重试', false);
    } finally {
        if (button) button.disabled = false;
    }
}

/* 会员专享提示：非会员点云控面板时弹出，可直接跳到账号设置的会员购买 */
function 显示会员专享弹窗(message) {
    const old = document.getElementById('jyVipGateModal');
    if (old) old.remove();
    const wrap = document.createElement('div');
    wrap.id = 'jyVipGateModal';
    wrap.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.45);display:flex;align-items:center;justify-content:center;z-index:100005;padding:20px;';
    wrap.innerHTML = `
        <div style="width:100%;max-width:380px;background:#fff;border-radius:18px;padding:26px 24px 20px;box-shadow:0 24px 60px rgba(15,23,42,.28);text-align:center;">
            <div style="width:56px;height:56px;border-radius:18px;background:linear-gradient(135deg,#fff3d1,#ffe6a8);display:flex;align-items:center;justify-content:center;margin:0 auto 14px;">
                <i class="fas fa-crown" style="font-size:24px;color:#d99a00;"></i>
            </div>
            <div style="font-size:18px;font-weight:700;color:#1d2939;">会员专享功能</div>
            <div style="font-size:13.5px;color:#667085;line-height:1.7;margin:8px 0 20px;">${escapeHtml(message || '请开通会员后使用该功能')}</div>
            <div style="display:flex;gap:10px;">
                <button type="button" data-role="later" style="flex:1;height:42px;border-radius:10px;border:1px solid #e4e7ec;background:#fff;color:#475467;font-size:14px;cursor:pointer;">稍后再说</button>
                <button type="button" data-role="buy" style="flex:1.2;height:42px;border-radius:10px;border:0;background:linear-gradient(135deg,#5b7cfa,#3b52d4);color:#fff;font-size:14px;font-weight:600;cursor:pointer;">去开通会员</button>
            </div>
        </div>`;
    document.body.appendChild(wrap);
    const close = () => wrap.remove();
    wrap.addEventListener('click', (e) => { if (e.target === wrap) close(); });
    wrap.querySelector('[data-role="later"]').onclick = close;
    wrap.querySelector('[data-role="buy"]').onclick = () => {
        close();
        if (typeof sidebarEventManager !== 'undefined') {
            sidebarEventManager.navigateTo('settings');
        } else {
            const item = document.querySelector('.nav-item[data-page="settings"]');
            if (item) item.click();
        }
        setTimeout(() => { if (typeof 充值会员 === 'function') 充值会员(); }, 450);
    };
}

/* 应用实例额度徽标：页面加载 / 创建 / 购买后刷新 */
async function 刷新实例额度() {
    const badge = document.getElementById('appQuotaBadge');
    if (!badge) return;
    try {
        const r = await fetch('/api/账号接口入口.php?action=me', { credentials: 'same-origin', cache: 'no-store' });
        const j = await r.json();
        if (!j || !j.success || !j.data) throw new Error('bad');
        const q = Math.max(0, parseInt(j.data.app_quota, 10) || 0);
        badge.textContent = '剩余额度 ' + q + ' 个';
        badge.style.background = q > 0 ? '#eef4ff' : '#f2f4f7';
        badge.style.color = q > 0 ? '#2563eb' : '#667085';
        badge.style.borderColor = q > 0 ? '#d7e4ff' : '#e4e7ec';
        badge.title = q > 0 ? '创建应用时优先抵扣，可购买积攒' : '暂无额度，可直接创建（扣 10 元）或点右侧购买';
    } catch (e) {
        badge.textContent = '剩余额度 —';
    }
}

