async function saveUnbindSettings(appId, appName) {
    const unbindLimitInput = document.getElementById('unbindLimitInput');
    const unbindDeductHoursInput = document.getElementById('unbindDeductHoursInput');
    const unbind间距Input = document.getElementById('unbind间距Input');
    
    if (!unbindLimitInput || !unbindDeductHoursInput || !unbind间距Input) {
        alert('无法找到输入元素', false);
        return;
    }
    
    const unbindLimit = parseInt(unbindLimitInput.value);
    const unbindDeductHours = parseInt(unbindDeductHoursInput.value);
    const unbind间距  = parseInt(unbind间距Input.value);
    
    // 验证输入
    if (isNaN(unbindLimit) || unbindLimit < 0 || unbindLimit > 999) {
        alert('请输入有效的解绑次数限制（0-999）', false);
        unbindLimitInput.focus();
        return;
    }
    
    if (isNaN(unbindDeductHours) || unbindDeductHours < 0 || unbindDeductHours > 9999) {
        alert('请输入有效的解绑扣时（0-9999小时）', false);
        unbindDeductHoursInput.focus();
        return;
    }
    
    
    if (isNaN(unbind间距) || unbind间距 < 0 || unbind间距 > 9999) {
        alert('请输入有效的解绑间距（0-9999小时）', false);
        unbind间距Input.focus();
        return;
    }
    if (!开发者UID || !开发者密码) {
        alert('请先登录', false);
        return;
    }
    
    try {
        const params = {
            action: 'update_unbind_settings',
            password: 开发者安全密码,
            app_id: appId,
            unbind_limit: unbindLimit,
            unbind_deduct_hours: unbindDeductHours,
            unbind_间距: unbind间距
        };
        
        const result = await POSTPHP(开发者UID, 开发者密码, 开发者Token, 获取API链接('app.php'), params);
        
        if (result.success) {
            alert('解绑设置已保存', 'success');
            
            const modal = document.querySelector('.simple-unbind-settings-modal');
            if (modal) modal.remove();
            
            加载实例(对接实例_当前页码);
        } else {
            alert('保存解绑设置失败: ' + result.message, false);
        }
    } catch (error) {
        alert('保存解绑设置时发生错误: ' + error.message, false);
    }
}


