function 应用VIP限制() {
    // 非 VIP 时禁用带 data-vip 的加密/签名选项，并在文案后标 [需VIP]
    const isVip = !!window.是否VIP;
    document.querySelectorAll('select option[data-vip="1"]').forEach(opt => {
        opt.disabled = !isVip;
        if (!isVip) {
            if (!opt.dataset.origText) opt.dataset.origText = opt.textContent;
            if (!opt.textContent.includes('[需开通VIP]')) {
                opt.textContent = opt.dataset.origText + ' [需开通VIP]';
            }
        } else if (opt.dataset.origText) {
            opt.textContent = opt.dataset.origText;
        }
    });

    // 如果当前选中的就是 VIP 项但已不是 VIP，回退到安全值
    if (!isVip) {
        const encSel = document.getElementById('encryptionFormat');
        if (encSel && encSel.selectedOptions[0] && encSel.selectedOptions[0].dataset.vip === '1') {
            encSel.value = '0';
        }
        const signSel = document.getElementById('qmtionFormat');
        if (signSel && signSel.selectedOptions[0] && signSel.selectedOptions[0].dataset.vip === '1') {
            signSel.value = '1';
        }
    }
}

function 应用VIP限制延迟() {
    setTimeout(应用VIP限制, 0);
    setTimeout(应用VIP限制, 300);
}

