async function 创建对接实例() {
    if (!confirm(`确定创建应用实例吗？（有实例额度优先抵扣，否则扣除 10 元余额）`)) {
        alert('操作被取消', false);
        return;
    }
    const modal = document.querySelector('.simple-create-app-modal');
    const appNameInput = modal ? modal.querySelector('#appNameInput') : null;
    const appidInput = modal ? modal.querySelector('#appidInput') : null;
    const createBtn = modal ? modal.querySelector('#createAppBtn') : null;
    
    if (!appNameInput || !appidInput || !createBtn) {
        alert('无法找到弹窗元素', false);
        return;
    }
    
    const appName = appNameInput.value.trim();
    const appid = appidInput.value.trim();
    const isValid = appid === "" || /^\d{5}$/.test(appid);
    if (!appName) {
        alert('请输入应用名称', false);
        appNameInput.focus();
        return;
    }
    if (!isValid) {
        alert('ID必须为5位数字', false);
        appNameInput.focus();
        return;
    }
    
    if (appName.length > 10) {
        alert('应用名称长度不合法', false);
        appNameInput.focus();
        return;
    }
    
    if (!开发者UID || !开发者密码) {
        alert('请先登录', false);
        return;
    }
    
    const originalHTML = createBtn.innerHTML;
    
    const spinner = document.createElement('i');
    spinner.className = 'fas fa-spinner fa-spin';
    spinner.style.marginRight = '6px';
    
    createBtn.innerHTML = '';
    createBtn.appendChild(spinner);
    createBtn.appendChild(document.createTextNode('创建中'));
    createBtn.disabled = true;
    createBtn.style.opacity = '0.8';
    
    try {
        const params = {
            action: 'create_app',
            password: 开发者安全密码,
            app_name: appName,
            app_id: appid
        };
        
        const result = await POSTPHP(开发者UID, 开发者密码, 开发者Token, 获取API链接('app.php'), params);
        
        if (result.success) {
            createBtn.innerHTML = originalHTML;
            createBtn.disabled = false;
            createBtn.style.opacity = '1';
            
            if (modal) modal.remove();
            alert('应用创建成功', 'success');
            
            加载实例();
        } else {
            createBtn.innerHTML = originalHTML;
            createBtn.disabled = false;
            createBtn.style.opacity = '1';
            
            alert('创建应用失败: ' + result.message, false);
            appNameInput.focus();
        }
    } catch (error) {
        createBtn.innerHTML = originalHTML;
        createBtn.disabled = false;
        createBtn.style.opacity = '1';
        
        alert('创建应用时发生错误: ' + error.message, false);
    }
}

