function 随机字符串(len) {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    let s = '';
    for (let i = 0; i < len; i++) {
        s += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return s;
}

async function 复制实例密钥(text) {
    const value = String(text == null ? '' : text);
    if (!value) { alert('没有可复制的密钥', false); return; }
    let copied = false;
    if (navigator.clipboard && window.isSecureContext) {
        try { await navigator.clipboard.writeText(value); copied = true; } catch (ignored) {}
    }
    if (!copied) {
        const previous = document.activeElement;
        const area = document.createElement('textarea');
        area.value = value;
        area.setAttribute('aria-label', '复制密钥');
        area.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;';
        document.body.appendChild(area);
        try {
            area.focus(); area.select(); area.setSelectionRange(0, area.value.length);
            copied = document.execCommand('copy');
        } catch (ignored) {}
        finally { area.remove(); if (previous && previous.focus) previous.focus(); }
    }
    alert(copied ? '已复制到剪贴板' : '复制失败，请允许剪贴板权限或手动选中复制', copied);
}
